+async function checkScrapeSources({ sb, ownerId }: Ctx): Promise<WatchdogCheck> {
+  // Guards the 2026-08-14 regression: every Greenhouse/Lever board slug 404'd,
+  // so only the Ashby fallback produced jobs and Jennifer silently saw the
+  // wrong list. jobs_nonzero stayed green on stale rows and hid it. Here we
+  // read the last successful scrape's per-source counts and warn if the PRIMARY
+  // path (Greenhouse) contributed nothing — the earliest honest signal of rot.
+  const { data, error } = await sb
+    .from("runs")
+    .select("detail,started_at")
+    .eq("owner_id", ownerId)
+    .eq("kind", "job_scrape")
+    .in("status", ["ok", "partial"])
+    .order("started_at", { ascending: false })
+    .limit(1)
+    .maybeSingle();
+
+  if (error) {
+    return { check_name: "scrape_sources", severity: "warn", message: `Could not read scrape sources: ${error.message}` };
+  }
+  const detail = (data?.detail ?? {}) as { by_source?: Record<string, number> };
+  const bySource = detail.by_source;
+  if (!bySource || Object.keys(bySource).length === 0) {
+    // Older runs predate by_source persistence — not an error, just unknown.
+    return { check_name: "scrape_sources", severity: "ok", message: "No per-source data yet (older run)." };
+  }
+  const greenhouse = bySource.greenhouse ?? 0;
+  const total = Object.values(bySource).reduce((a, b) => a + b, 0);
+  if (greenhouse === 0) {
+    return {
+      check_name: "scrape_sources",
+      severity: "warn",
+      message: `Primary path dead: last scrape got 0 Greenhouse jobs (total ${total}). Run scripts/verify-targets.mjs — slugs likely 404.`,
+    };
+  }
+  return {
+    check_name: "scrape_sources",
+    severity: "ok",
+    message: `Greenhouse produced ${greenhouse} of ${total} raw jobs last scrape.`,
+  };
+}
